import{_ as t,o as a,c as i,ai as n}from"./chunks/framework.CUYGB37K.js";const h=JSON.parse('{"title":"AI Agent Analytics","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/ai-agent/analytics.md","filePath":"2.0/ai-agent/analytics.md","lastUpdated":1776149834000}'),o={name:"2.0/ai-agent/analytics.md"};function s(r,e,l,d,g,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-agent-analytics" tabindex="-1">AI Agent Analytics <a class="header-anchor" href="#ai-agent-analytics" aria-label="Permalink to &quot;AI Agent Analytics&quot;">​</a></h1><p>The AI Agent Analytics dashboard provides visibility into how the AI Agent is being used across your organization. It tracks token consumption, usage patterns, and costs, helping you manage your AI budget effectively.</p><h2 id="analytics-dashboard-overview" tabindex="-1">Analytics Dashboard Overview <a class="header-anchor" href="#analytics-dashboard-overview" aria-label="Permalink to &quot;Analytics Dashboard Overview&quot;">​</a></h2><p>The AI Agent Analytics dashboard gives you a centralized view of all AI Agent activity. From this dashboard, you can monitor:</p><ul><li><strong>Total tokens consumed</strong> over a selected time period.</li><li><strong>Number of conversations</strong> initiated by each admin user.</li><li><strong>Number of tool calls</strong> executed by the AI Agent.</li><li><strong>Daily and weekly usage trends</strong> displayed in visual charts.</li></ul><p>This dashboard is accessible from the admin panel and is available to users with the appropriate permissions.</p><h2 id="token-budget-tracking" tabindex="-1">Token Budget Tracking <a class="header-anchor" href="#token-budget-tracking" aria-label="Permalink to &quot;Token Budget Tracking&quot;">​</a></h2><p>The AI Agent operates on a <strong>daily token budget</strong> system. Each interaction with the AI Agent consumes tokens based on the complexity and length of the request and response. The analytics dashboard displays:</p><ul><li><strong>Daily token usage</strong> — How many tokens have been consumed today.</li><li><strong>Remaining budget</strong> — How many tokens are still available for the current day.</li><li><strong>Budget utilization percentage</strong> — A visual indicator showing how much of the daily budget has been used.</li></ul><p>When the daily token budget is exhausted, the AI Agent will notify you that the limit has been reached and will resume normal operation the following day when the budget resets.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep an eye on the daily token usage if your team relies heavily on auto-enrichment or bulk operations, as these tasks tend to consume more tokens than simple queries.</p></div><h2 id="monitoring-ai-usage-and-costs" tabindex="-1">Monitoring AI Usage and Costs <a class="header-anchor" href="#monitoring-ai-usage-and-costs" aria-label="Permalink to &quot;Monitoring AI Usage and Costs&quot;">​</a></h2><p>The analytics dashboard helps you understand the cost implications of AI Agent usage. Key metrics include:</p><ul><li><strong>Token consumption per user</strong> — See which team members are using the AI Agent most frequently.</li><li><strong>Token consumption per operation type</strong> — Identify which types of operations (e.g., product creation, auto-enrichment, data quality scans) consume the most tokens.</li><li><strong>Cost estimation</strong> — Based on your AI provider&#39;s pricing, the dashboard can display an estimated cost for the tokens consumed.</li></ul><p>This information is valuable for budgeting and for identifying opportunities to optimize usage.</p><h2 id="configuring-daily-token-budgets" tabindex="-1">Configuring Daily Token Budgets <a class="header-anchor" href="#configuring-daily-token-budgets" aria-label="Permalink to &quot;Configuring Daily Token Budgets&quot;">​</a></h2><p>To set or adjust the daily token budget:</p><ol><li>Navigate to <strong>Configuration &gt;&gt; AI Agent</strong> in the admin panel.</li><li>Locate the <strong>Daily Token Budget</strong> setting.</li><li>Enter the maximum number of tokens allowed per day.</li><li>Click <strong>Save Configuration</strong> to apply the change.</li></ol><p>The budget applies globally across all admin users. Once the combined usage of all users reaches the daily limit, the AI Agent will pause until the next day.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Start with a conservative daily budget and increase it gradually as you understand your team&#39;s typical usage patterns. This prevents unexpected spikes in AI costs.</p></div><h2 id="viewing-usage-history-and-trends" tabindex="-1">Viewing Usage History and Trends <a class="header-anchor" href="#viewing-usage-history-and-trends" aria-label="Permalink to &quot;Viewing Usage History and Trends&quot;">​</a></h2><p>The analytics dashboard includes a <strong>Usage History</strong> section where you can review past activity over customizable date ranges. This section provides:</p><ul><li><strong>Daily usage breakdown</strong> — A day-by-day view of token consumption and conversation counts.</li><li><strong>Weekly and monthly summaries</strong> — Aggregated views for longer-term trend analysis.</li><li><strong>Peak usage identification</strong> — Highlights days or periods with unusually high usage so you can investigate and plan accordingly.</li></ul><p>Use this historical data to make informed decisions about token budget allocation, team training, and workflow optimization.</p>',24)])])}const p=t(o,[["render",s]]);export{h as __pageData,p as default};
